-- ============================================================
-- Migration: Rebind rating-writing RPCs / triggers to the new
--            4-column unique on campaign_activity_ratings.
--
-- Migration 20260424110000 dropped the legacy 2-column UNIQUE
-- (activity_id, worker_id) and introduced
-- UNIQUE NULLS NOT DISTINCT (activity_id, worker_id,
--                            rating_phase, event_id)
-- so any existing "ON CONFLICT (activity_id, worker_id)" clause
-- would fail at runtime. This migration updates the two DB
-- writers that still use it:
--
--   1. record_call_attempt()  — call-outcome-derived ratings
--   2. fn_auto_promote_task_list_leader() — auto-rate=1 on task take
--
-- Function bodies are preserved 1:1 apart from the INSERT /
-- ON CONFLICT clauses (explicit rating_phase='actual',
-- event_id=NULL). The composite-rating logic itself is kept as-is
-- in Phase 2; Phase 6 replaces it with a per-outcome mapping.
-- ============================================================

-- -----------------------------------------------------------
-- 1. record_call_attempt — copy of the 20260417100000 body
--    with the upsert conflict target updated.
-- -----------------------------------------------------------
CREATE OR REPLACE FUNCTION record_call_attempt(
  p_list_item_id INTEGER,
  p_script_id INTEGER,
  p_caller_user_id UUID,
  p_dial_disposition VARCHAR(30),
  p_call_disposition VARCHAR(30) DEFAULT NULL,
  p_overall_notes TEXT DEFAULT NULL,
  p_callback_datetime TIMESTAMPTZ DEFAULT NULL,
  p_support_level VARCHAR(30) DEFAULT NULL,
  p_follow_up_action TEXT DEFAULT NULL,
  p_cta_response VARCHAR(20) DEFAULT NULL,
  p_duration_seconds INTEGER DEFAULT NULL,
  p_step_outcomes JSONB DEFAULT '[]',
  p_outcome_ids INTEGER[] DEFAULT '{}',
  p_outcome_entries JSONB DEFAULT '[]'
)
RETURNS JSONB AS $$
DECLARE
  v_attempt_id INTEGER;
  v_worker_id INTEGER;
  v_campaign_id INTEGER;
  v_list_id INTEGER;
  v_connection_id BIGINT;
  v_item_status VARCHAR(20);
  v_step JSONB;
  v_result JSONB;
  v_outcome_id INTEGER;
  v_outcome_row RECORD;
  v_positive_count INTEGER := 0;
  v_negative_count INTEGER := 0;
  v_neutral_count INTEGER := 0;
  v_activity_id INTEGER;
  v_rating INTEGER;
  v_entry JSONB;
  v_response_value TEXT;
  v_resolved_script_id INTEGER;
BEGIN
  SELECT cli.worker_id, cl.campaign_id, cli.list_id
  INTO v_worker_id, v_campaign_id, v_list_id
  FROM call_list_items cli
  JOIN call_lists cl ON cl.list_id = cli.list_id
  WHERE cli.item_id = p_list_item_id;

  IF v_worker_id IS NULL THEN
    RAISE EXCEPTION 'call_list_item % not found', p_list_item_id;
  END IF;

  v_resolved_script_id := resolve_outcomes_script_id(COALESCE(p_script_id, 0));
  IF v_resolved_script_id = 0 THEN
    v_resolved_script_id := NULL;
  END IF;

  -- 1. Insert call_attempt
  INSERT INTO call_attempts (
    list_item_id, script_id, caller_user_id,
    dial_disposition, call_disposition,
    overall_notes, callback_datetime, support_level_assessed,
    follow_up_action, cta_response, duration_seconds,
    ended_at
  ) VALUES (
    p_list_item_id, p_script_id, p_caller_user_id,
    p_dial_disposition, p_call_disposition,
    p_overall_notes, p_callback_datetime, p_support_level,
    p_follow_up_action, p_cta_response, p_duration_seconds,
    CASE WHEN p_duration_seconds IS NOT NULL THEN now() ELSE NULL END
  )
  RETURNING attempt_id INTO v_attempt_id;

  -- 2. Insert step outcomes
  FOR v_step IN SELECT * FROM jsonb_array_elements(p_step_outcomes)
  LOOP
    INSERT INTO call_step_outcomes (
      attempt_id, section_id, reached, outcome_value, notes, duration_seconds, sort_order
    ) VALUES (
      v_attempt_id,
      (v_step->>'section_id')::INTEGER,
      COALESCE((v_step->>'reached')::BOOLEAN, false),
      v_step->>'outcome_value',
      v_step->>'notes',
      (v_step->>'duration_seconds')::INTEGER,
      COALESCE((v_step->>'sort_order')::INTEGER, 0)
    );
  END LOOP;

  -- 2b. Process outcome entries (JSONB format with response_value)
  IF jsonb_array_length(p_outcome_entries) > 0 THEN
    FOR v_entry IN SELECT * FROM jsonb_array_elements(p_outcome_entries)
    LOOP
      v_outcome_id := (v_entry->>'outcome_id')::INTEGER;
      v_response_value := v_entry->>'response_value';

      INSERT INTO call_attempt_outcomes (attempt_id, outcome_id, response_value)
      VALUES (v_attempt_id, v_outcome_id, v_response_value)
      ON CONFLICT (attempt_id, outcome_id) DO UPDATE SET response_value = EXCLUDED.response_value;

      SELECT cod.is_positive, cod.activity_id, cod.outcome_category
      INTO v_outcome_row
      FROM call_outcome_definitions cod
      WHERE cod.outcome_id = v_outcome_id;

      IF v_outcome_row.is_positive THEN
        v_positive_count := v_positive_count + 1;
      ELSIF v_outcome_row.outcome_category = 'cta' AND NOT v_outcome_row.is_positive THEN
        v_negative_count := v_negative_count + 1;
      ELSE
        v_neutral_count := v_neutral_count + 1;
      END IF;
    END LOOP;

  -- 2c. Legacy: p_outcome_ids (backward compat with old INTEGER[] format)
  ELSIF array_length(p_outcome_ids, 1) > 0 THEN
    FOREACH v_outcome_id IN ARRAY p_outcome_ids
    LOOP
      INSERT INTO call_attempt_outcomes (attempt_id, outcome_id)
      VALUES (v_attempt_id, v_outcome_id)
      ON CONFLICT DO NOTHING;

      SELECT cod.is_positive, cod.activity_id, cod.outcome_category
      INTO v_outcome_row
      FROM call_outcome_definitions cod
      WHERE cod.outcome_id = v_outcome_id;

      IF v_outcome_row.is_positive THEN
        v_positive_count := v_positive_count + 1;
      ELSIF v_outcome_row.outcome_category = 'cta' AND NOT v_outcome_row.is_positive THEN
        v_negative_count := v_negative_count + 1;
      ELSE
        v_neutral_count := v_neutral_count + 1;
      END IF;
    END LOOP;
  END IF;

  -- 2d. Derive composite rating and write to assessment system.
  --     NOTE: Phase 6 replaces this composite with a per-outcome
  --     maps_to_rating_level mapping. The explicit rating_phase='actual'
  --     and event_id=NULL keep this write aligned with the new
  --     4-column unique constraint.
  IF v_positive_count + v_negative_count + v_neutral_count > 0 AND v_resolved_script_id IS NOT NULL THEN
    v_activity_id := (
      SELECT cod2.activity_id FROM call_outcome_definitions cod2
      WHERE cod2.script_id = v_resolved_script_id
        AND cod2.activity_id IS NOT NULL
      LIMIT 1
    );

    IF v_activity_id IS NOT NULL AND v_campaign_id IS NOT NULL THEN
      IF v_positive_count > 0 AND v_negative_count = 0 THEN
        v_rating := 4;
      ELSIF v_positive_count > 0 AND v_negative_count > 0 THEN
        v_rating := 3;
      ELSIF v_negative_count > 0 THEN
        v_rating := 2;
      ELSE
        v_rating := 3;
      END IF;

      INSERT INTO campaign_activity_ratings (
        activity_id, worker_id, rating, source, rated_at, rating_phase, event_id
      )
      VALUES (
        v_activity_id, v_worker_id, v_rating, 'call_outcome', now(), 'actual', NULL
      )
      ON CONFLICT (activity_id, worker_id, rating_phase, event_id) DO UPDATE SET
        rating = EXCLUDED.rating,
        rated_at = EXCLUDED.rated_at,
        source = EXCLUDED.source;
    END IF;
  END IF;

  -- 2e. Membership / ambition side effects
  PERFORM apply_call_outcome_side_effects(v_attempt_id, v_worker_id, v_campaign_id);

  -- 3. Determine new item status
  IF p_dial_disposition = 'callback_requested' OR p_call_disposition = 'partial_asked_callback' THEN
    v_item_status := 'deferred';
  ELSIF p_dial_disposition = 'connected' AND p_call_disposition IS NOT NULL THEN
    v_item_status := 'completed';
  ELSIF p_dial_disposition IN ('disconnected', 'wrong_number', 'do_not_call') THEN
    v_item_status := 'completed';
  ELSE
    v_item_status := 'pending';
  END IF;

  -- 4. Update call_list_items
  UPDATE call_list_items SET
    status = v_item_status,
    attempts_count = attempts_count + 1,
    last_attempt_at = now(),
    best_disposition = COALESCE(p_call_disposition, p_dial_disposition),
    next_call_at = p_callback_datetime,
    updated_at = now()
  WHERE item_id = p_list_item_id;

  -- 5. Update call_lists completed_items count
  UPDATE call_lists SET
    completed_items = (
      SELECT COUNT(*) FROM call_list_items
      WHERE list_id = v_list_id AND status IN ('completed', 'skipped')
    ),
    updated_at = now()
  WHERE list_id = v_list_id;

  -- 6. Upsert worker_campaign_connections
  IF v_campaign_id IS NOT NULL THEN
    SELECT connection_id INTO v_connection_id
    FROM worker_campaign_connections
    WHERE worker_id = v_worker_id AND campaign_id = v_campaign_id;

    IF v_connection_id IS NULL THEN
      INSERT INTO worker_campaign_connections (
        worker_id, campaign_id, connection_status,
        first_contacted_at, last_contacted_at, contact_count,
        preferred_contact_method, support_level, created_by
      ) VALUES (
        v_worker_id, v_campaign_id,
        CASE
          WHEN p_dial_disposition = 'connected' THEN 'contacted'
          ELSE 'potential'
        END,
        now(), now(), 1,
        'phone',
        p_support_level,
        p_caller_user_id
      )
      RETURNING connection_id INTO v_connection_id;
    ELSE
      UPDATE worker_campaign_connections SET
        connection_status = CASE
          WHEN p_dial_disposition = 'connected'
            AND connection_status IN ('potential', 'contacted') THEN 'engaged'
          WHEN p_dial_disposition = 'connected' THEN connection_status
          ELSE connection_status
        END,
        last_contacted_at = now(),
        contact_count = contact_count + 1,
        support_level = COALESCE(p_support_level, support_level),
        updated_at = now()
      WHERE connection_id = v_connection_id;
    END IF;

    -- 7. Insert worker_activity_log
    INSERT INTO worker_activity_log (
      connection_id, activity_type, activity_date,
      description, outcome, contact_method,
      duration_minutes, logged_by
    ) VALUES (
      v_connection_id, 'contact', now(),
      COALESCE(p_overall_notes, 'Phone call attempt'),
      COALESCE(p_call_disposition, p_dial_disposition),
      'phone',
      CASE WHEN p_duration_seconds IS NOT NULL
        THEN CEIL(p_duration_seconds / 60.0)::INTEGER
        ELSE NULL
      END,
      p_caller_user_id
    );
  END IF;

  v_result := jsonb_build_object(
    'attempt_id', v_attempt_id,
    'item_status', v_item_status,
    'connection_id', v_connection_id,
    'worker_id', v_worker_id,
    'campaign_id', v_campaign_id
  );

  RETURN v_result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- -----------------------------------------------------------
-- 2. fn_auto_promote_task_list_leader — same behaviour,
--    updated conflict target.
-- -----------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_auto_promote_task_list_leader()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.leader_worker_id IS NOT NULL THEN
    -- Promote to Activist if currently no role or Contact
    UPDATE workers
    SET member_role_type_id = 8  -- Activist
    WHERE worker_id = NEW.leader_worker_id
      AND (member_role_type_id IS NULL OR member_role_type_id = 3);

    -- Auto-rate the leader as 1 (supportive leader) for the linked
    -- activity. Phase 4 extends this to propagate across every
    -- worker_assessable ambition linked in activity_ambitions.
    IF NEW.activity_id IS NOT NULL THEN
      INSERT INTO campaign_activity_ratings
        (activity_id, worker_id, rating, source, rated_at, rating_phase, event_id)
      VALUES
        (NEW.activity_id, NEW.leader_worker_id, 1, 'task_take', now(), 'actual', NULL)
      ON CONFLICT (activity_id, worker_id, rating_phase, event_id) DO NOTHING;
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ============================================================
-- Migration: record_assessment_event() shared RPC + triggers
--
-- Single entry point for every activity source (SMS, email,
-- petition, meeting, staff, leader form, task-take, call outcome)
-- to upsert a campaign_activity_rating. Centralising the write
-- makes conflict resolution (Phase 5) and audit logging much
-- simpler, because every rating goes through one function.
--
-- Triggers on the Phase 3 capture tables translate domain events
-- (signed a petition, replied 'yes' to SMS, attended a meeting)
-- into a rating via this RPC.
-- ============================================================

-- -----------------------------------------------------------
-- 1. record_assessment_event — single upsert entry point
-- -----------------------------------------------------------
CREATE OR REPLACE FUNCTION record_assessment_event(
  p_activity_id INT,
  p_worker_id INT,
  p_rating INT DEFAULT NULL,
  p_binary_value VARCHAR DEFAULT NULL,
  p_rating_phase VARCHAR DEFAULT 'actual',
  p_event_id INT DEFAULT NULL,
  p_source VARCHAR DEFAULT 'staff',
  p_notes TEXT DEFAULT NULL,
  p_actor_id UUID DEFAULT NULL
) RETURNS INT AS $$
DECLARE
  v_rating_id INT;
BEGIN
  IF p_rating IS NULL AND p_binary_value IS NULL THEN
    RAISE EXCEPTION
      'record_assessment_event: at least one of p_rating or p_binary_value must be non-null';
  END IF;

  IF p_rating IS NOT NULL AND (p_rating < 1 OR p_rating > 5) THEN
    RAISE EXCEPTION
      'record_assessment_event: p_rating must be 1..5 (got %)', p_rating;
  END IF;

  IF p_rating_phase NOT IN ('expected', 'actual') THEN
    RAISE EXCEPTION
      'record_assessment_event: p_rating_phase must be expected or actual (got %)', p_rating_phase;
  END IF;

  INSERT INTO campaign_activity_ratings (
    activity_id, worker_id, rating, binary_value, notes,
    source, rated_at, rated_by_user_id, rating_phase, event_id
  )
  VALUES (
    p_activity_id, p_worker_id, p_rating, p_binary_value, p_notes,
    p_source, now(), p_actor_id, p_rating_phase, p_event_id
  )
  ON CONFLICT (activity_id, worker_id, rating_phase, event_id) DO UPDATE SET
    rating = COALESCE(EXCLUDED.rating, campaign_activity_ratings.rating),
    binary_value = COALESCE(EXCLUDED.binary_value, campaign_activity_ratings.binary_value),
    notes = COALESCE(EXCLUDED.notes, campaign_activity_ratings.notes),
    source = EXCLUDED.source,
    rated_at = EXCLUDED.rated_at,
    rated_by_user_id = COALESCE(EXCLUDED.rated_by_user_id, campaign_activity_ratings.rated_by_user_id)
  RETURNING rating_id INTO v_rating_id;

  RETURN v_rating_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION record_assessment_event TO authenticated;

COMMENT ON FUNCTION record_assessment_event IS
  'Single upsert entry point for campaign_activity_ratings. Validates '
  'rating range and phase; returns the rating_id. Other sources (SMS, '
  'email, petition, meeting, staff UI) should funnel through this.';

-- -----------------------------------------------------------
-- 2. sms_interactions -> rating trigger
--    Fires only when the row implies an assessable response:
--    direction='inbound' AND (maps_to_rating OR maps_to_binary
--    OR cta_response) AND activity_id IS NOT NULL.
-- -----------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_sms_to_rating()
RETURNS TRIGGER AS $$
DECLARE
  v_rating INT;
  v_binary VARCHAR;
BEGIN
  IF NEW.direction <> 'inbound' OR NEW.activity_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_rating := NEW.maps_to_rating;
  v_binary := NEW.maps_to_binary;

  -- Derive from cta_response if the caller didn't specify
  IF v_rating IS NULL AND v_binary IS NULL AND NEW.cta_response IS NOT NULL THEN
    v_binary := NEW.cta_response;
  END IF;

  IF v_rating IS NULL AND v_binary IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM record_assessment_event(
    p_activity_id := NEW.activity_id,
    p_worker_id := NEW.worker_id,
    p_rating := v_rating,
    p_binary_value := v_binary,
    p_rating_phase := 'actual',
    p_event_id := NULL,
    p_source := 'sms',
    p_notes := NEW.notes,
    p_actor_id := NEW.created_by
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS trg_sms_to_rating ON sms_interactions;
CREATE TRIGGER trg_sms_to_rating
  AFTER INSERT ON sms_interactions
  FOR EACH ROW EXECUTE FUNCTION fn_sms_to_rating();

-- -----------------------------------------------------------
-- 3. email_cta_responses -> rating trigger
--    Only 'clicked', 'replied', 'form_submitted' are treated
--    as assessable events. Opens / bounces / unsubscribes
--    don't produce ratings.
-- -----------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_email_cta_to_rating()
RETURNS TRIGGER AS $$
DECLARE
  v_rating INT;
  v_binary VARCHAR;
BEGIN
  IF NEW.activity_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.email_event NOT IN ('clicked', 'replied', 'form_submitted') THEN
    RETURN NEW;
  END IF;

  v_rating := NEW.maps_to_rating;
  v_binary := NEW.maps_to_binary;

  IF v_rating IS NULL AND v_binary IS NULL AND NEW.cta_response IS NOT NULL THEN
    v_binary := NEW.cta_response;
  END IF;

  IF v_rating IS NULL AND v_binary IS NULL THEN
    -- A click / reply without further signal implies supporter
    v_rating := 2;
  END IF;

  PERFORM record_assessment_event(
    p_activity_id := NEW.activity_id,
    p_worker_id := NEW.worker_id,
    p_rating := v_rating,
    p_binary_value := v_binary,
    p_rating_phase := 'actual',
    p_event_id := NULL,
    p_source := 'email',
    p_notes := NEW.notes,
    p_actor_id := NEW.created_by
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS trg_email_cta_to_rating ON email_cta_responses;
CREATE TRIGGER trg_email_cta_to_rating
  AFTER INSERT ON email_cta_responses
  FOR EACH ROW EXECUTE FUNCTION fn_email_cta_to_rating();

-- -----------------------------------------------------------
-- 4. petition_signatures -> rating trigger
--    A signature = supporter (rating 2) by default.
-- -----------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_petition_to_rating()
RETURNS TRIGGER AS $$
BEGIN
  PERFORM record_assessment_event(
    p_activity_id := NEW.activity_id,
    p_worker_id := NEW.worker_id,
    p_rating := 2,
    p_binary_value := 'signed',
    p_rating_phase := 'actual',
    p_event_id := NULL,
    p_source := 'petition',
    p_notes := NEW.notes,
    p_actor_id := NEW.created_by
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS trg_petition_to_rating ON petition_signatures;
CREATE TRIGGER trg_petition_to_rating
  AFTER INSERT ON petition_signatures
  FOR EACH ROW EXECUTE FUNCTION fn_petition_to_rating();

-- -----------------------------------------------------------
-- 5. meeting_attendance -> rating trigger
--    Maps status to rating_phase + binary_value:
--      attending / not_attending  => phase=expected
--      attended / did_not_attend / abstain / unknown => phase=actual
-- -----------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_meeting_attendance_to_rating()
RETURNS TRIGGER AS $$
DECLARE
  v_activity_id INT;
  v_phase VARCHAR(10);
BEGIN
  SELECT activity_id INTO v_activity_id
  FROM activity_events
  WHERE event_id = NEW.event_id;

  IF v_activity_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_phase := CASE
    WHEN NEW.status IN ('attending', 'not_attending') THEN 'expected'
    ELSE 'actual'
  END;

  PERFORM record_assessment_event(
    p_activity_id := v_activity_id,
    p_worker_id := NEW.worker_id,
    p_rating := NULL,
    p_binary_value := NEW.status,
    p_rating_phase := v_phase,
    p_event_id := NEW.event_id,
    p_source := 'meeting',
    p_notes := NEW.notes,
    p_actor_id := NEW.created_by
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS trg_meeting_attendance_to_rating ON meeting_attendance;
CREATE TRIGGER trg_meeting_attendance_to_rating
  AFTER INSERT OR UPDATE OF status ON meeting_attendance
  FOR EACH ROW EXECUTE FUNCTION fn_meeting_attendance_to_rating();

-- ============================================================
-- Migration: Call outcome explicit rating mapping
--
-- The existing composite rule in record_call_attempt()
-- flattens every call into one of {2, 3, 4} based on counts of
-- positive / negative / neutral outcomes. That's too coarse:
-- a clear "supportive leader" outcome (e.g. "Committed to
-- organising workmates") ends up rated 4 (opposed) next to a
-- "cool" outcome because the code doesn't know that the former
-- is rating level 1.
--
-- This migration:
--   1. Adds maps_to_rating_level (1..5) and maps_to_binary_value
--      columns to call_outcome_definitions.
--   2. Rewrites record_call_attempt's rating-derivation step:
--      * If any selected outcome defines maps_to_rating_level,
--        take the BEST (lowest numeric) value among positive
--        outcomes AND the WORST (highest numeric) among negative
--        outcomes; pick whichever is more informative.
--      * Fall back to the legacy composite (2 / 3 / 4) only when
--        no outcome has an explicit mapping.
--   3. maps_to_ambition_id remains for per-outcome reporting
--      but is no longer the propagation path (ambition rollup is
--      now through activity_ambitions + the rollup views).
-- ============================================================

-- 1. New columns on call_outcome_definitions
ALTER TABLE call_outcome_definitions
  ADD COLUMN IF NOT EXISTS maps_to_rating_level INT
    CHECK (maps_to_rating_level IS NULL OR (maps_to_rating_level BETWEEN 1 AND 5)),
  ADD COLUMN IF NOT EXISTS maps_to_binary_value VARCHAR(30);

COMMENT ON COLUMN call_outcome_definitions.maps_to_rating_level IS
  'Explicit rating (1..5) produced when this outcome is recorded. '
  'Takes precedence over the legacy is_positive / outcome_category '
  'composite. NULL = use legacy composite.';

COMMENT ON COLUMN call_outcome_definitions.maps_to_binary_value IS
  'Optional binary_value (e.g. yes/no/DNP) written to the rating '
  'alongside maps_to_rating_level. Used for outcome questions that '
  'record a structured response as well as a rating.';

-- 2. Rewrite record_call_attempt with explicit-mapping preference.
--    Body is identical to the previous version (20260424120000)
--    except for the "Derive composite rating" block.
CREATE OR REPLACE FUNCTION record_call_attempt(
  p_list_item_id INTEGER,
  p_script_id INTEGER,
  p_caller_user_id UUID,
  p_dial_disposition VARCHAR(30),
  p_call_disposition VARCHAR(30) DEFAULT NULL,
  p_overall_notes TEXT DEFAULT NULL,
  p_callback_datetime TIMESTAMPTZ DEFAULT NULL,
  p_support_level VARCHAR(30) DEFAULT NULL,
  p_follow_up_action TEXT DEFAULT NULL,
  p_cta_response VARCHAR(20) DEFAULT NULL,
  p_duration_seconds INTEGER DEFAULT NULL,
  p_step_outcomes JSONB DEFAULT '[]',
  p_outcome_ids INTEGER[] DEFAULT '{}',
  p_outcome_entries JSONB DEFAULT '[]'
)
RETURNS JSONB AS $$
DECLARE
  v_attempt_id INTEGER;
  v_worker_id INTEGER;
  v_campaign_id INTEGER;
  v_list_id INTEGER;
  v_connection_id BIGINT;
  v_item_status VARCHAR(20);
  v_step JSONB;
  v_result JSONB;
  v_outcome_id INTEGER;
  v_outcome_row RECORD;
  v_positive_count INTEGER := 0;
  v_negative_count INTEGER := 0;
  v_neutral_count INTEGER := 0;
  v_activity_id INTEGER;
  v_rating INTEGER;
  v_binary_value VARCHAR(30);
  v_best_positive INTEGER := NULL;
  v_worst_negative INTEGER := NULL;
  v_any_explicit BOOLEAN := FALSE;
  v_entry JSONB;
  v_response_value TEXT;
  v_resolved_script_id INTEGER;
BEGIN
  SELECT cli.worker_id, cl.campaign_id, cli.list_id
  INTO v_worker_id, v_campaign_id, v_list_id
  FROM call_list_items cli
  JOIN call_lists cl ON cl.list_id = cli.list_id
  WHERE cli.item_id = p_list_item_id;

  IF v_worker_id IS NULL THEN
    RAISE EXCEPTION 'call_list_item % not found', p_list_item_id;
  END IF;

  v_resolved_script_id := resolve_outcomes_script_id(COALESCE(p_script_id, 0));
  IF v_resolved_script_id = 0 THEN
    v_resolved_script_id := NULL;
  END IF;

  -- 1. Insert call_attempt
  INSERT INTO call_attempts (
    list_item_id, script_id, caller_user_id,
    dial_disposition, call_disposition,
    overall_notes, callback_datetime, support_level_assessed,
    follow_up_action, cta_response, duration_seconds,
    ended_at
  ) VALUES (
    p_list_item_id, p_script_id, p_caller_user_id,
    p_dial_disposition, p_call_disposition,
    p_overall_notes, p_callback_datetime, p_support_level,
    p_follow_up_action, p_cta_response, p_duration_seconds,
    CASE WHEN p_duration_seconds IS NOT NULL THEN now() ELSE NULL END
  )
  RETURNING attempt_id INTO v_attempt_id;

  -- 2. Insert step outcomes
  FOR v_step IN SELECT * FROM jsonb_array_elements(p_step_outcomes)
  LOOP
    INSERT INTO call_step_outcomes (
      attempt_id, section_id, reached, outcome_value, notes, duration_seconds, sort_order
    ) VALUES (
      v_attempt_id,
      (v_step->>'section_id')::INTEGER,
      COALESCE((v_step->>'reached')::BOOLEAN, false),
      v_step->>'outcome_value',
      v_step->>'notes',
      (v_step->>'duration_seconds')::INTEGER,
      COALESCE((v_step->>'sort_order')::INTEGER, 0)
    );
  END LOOP;

  -- 2b. Process outcome entries (JSONB format with response_value)
  IF jsonb_array_length(p_outcome_entries) > 0 THEN
    FOR v_entry IN SELECT * FROM jsonb_array_elements(p_outcome_entries)
    LOOP
      v_outcome_id := (v_entry->>'outcome_id')::INTEGER;
      v_response_value := v_entry->>'response_value';

      INSERT INTO call_attempt_outcomes (attempt_id, outcome_id, response_value)
      VALUES (v_attempt_id, v_outcome_id, v_response_value)
      ON CONFLICT (attempt_id, outcome_id) DO UPDATE SET response_value = EXCLUDED.response_value;

      SELECT cod.is_positive, cod.activity_id, cod.outcome_category,
             cod.maps_to_rating_level, cod.maps_to_binary_value
      INTO v_outcome_row
      FROM call_outcome_definitions cod
      WHERE cod.outcome_id = v_outcome_id;

      IF v_outcome_row.maps_to_rating_level IS NOT NULL THEN
        v_any_explicit := TRUE;
        IF v_outcome_row.maps_to_rating_level <= 2 THEN
          IF v_best_positive IS NULL OR v_outcome_row.maps_to_rating_level < v_best_positive THEN
            v_best_positive := v_outcome_row.maps_to_rating_level;
          END IF;
        ELSIF v_outcome_row.maps_to_rating_level >= 4 THEN
          IF v_worst_negative IS NULL OR v_outcome_row.maps_to_rating_level > v_worst_negative THEN
            v_worst_negative := v_outcome_row.maps_to_rating_level;
          END IF;
        END IF;
        IF v_outcome_row.maps_to_binary_value IS NOT NULL THEN
          v_binary_value := v_outcome_row.maps_to_binary_value;
        END IF;
      END IF;

      IF v_outcome_row.is_positive THEN
        v_positive_count := v_positive_count + 1;
      ELSIF v_outcome_row.outcome_category = 'cta' AND NOT v_outcome_row.is_positive THEN
        v_negative_count := v_negative_count + 1;
      ELSE
        v_neutral_count := v_neutral_count + 1;
      END IF;
    END LOOP;

  -- 2c. Legacy p_outcome_ids path (backward compat)
  ELSIF array_length(p_outcome_ids, 1) > 0 THEN
    FOREACH v_outcome_id IN ARRAY p_outcome_ids
    LOOP
      INSERT INTO call_attempt_outcomes (attempt_id, outcome_id)
      VALUES (v_attempt_id, v_outcome_id)
      ON CONFLICT DO NOTHING;

      SELECT cod.is_positive, cod.activity_id, cod.outcome_category,
             cod.maps_to_rating_level, cod.maps_to_binary_value
      INTO v_outcome_row
      FROM call_outcome_definitions cod
      WHERE cod.outcome_id = v_outcome_id;

      IF v_outcome_row.maps_to_rating_level IS NOT NULL THEN
        v_any_explicit := TRUE;
        IF v_outcome_row.maps_to_rating_level <= 2 THEN
          IF v_best_positive IS NULL OR v_outcome_row.maps_to_rating_level < v_best_positive THEN
            v_best_positive := v_outcome_row.maps_to_rating_level;
          END IF;
        ELSIF v_outcome_row.maps_to_rating_level >= 4 THEN
          IF v_worst_negative IS NULL OR v_outcome_row.maps_to_rating_level > v_worst_negative THEN
            v_worst_negative := v_outcome_row.maps_to_rating_level;
          END IF;
        END IF;
        IF v_outcome_row.maps_to_binary_value IS NOT NULL THEN
          v_binary_value := v_outcome_row.maps_to_binary_value;
        END IF;
      END IF;

      IF v_outcome_row.is_positive THEN
        v_positive_count := v_positive_count + 1;
      ELSIF v_outcome_row.outcome_category = 'cta' AND NOT v_outcome_row.is_positive THEN
        v_negative_count := v_negative_count + 1;
      ELSE
        v_neutral_count := v_neutral_count + 1;
      END IF;
    END LOOP;
  END IF;

  -- 2d. Derive rating.
  --     Prefer explicit maps_to_rating_level mapping; fall back to the
  --     legacy composite only when no explicit mapping was selected.
  IF v_positive_count + v_negative_count + v_neutral_count > 0 AND v_resolved_script_id IS NOT NULL THEN
    v_activity_id := (
      SELECT cod2.activity_id FROM call_outcome_definitions cod2
      WHERE cod2.script_id = v_resolved_script_id
        AND cod2.activity_id IS NOT NULL
      LIMIT 1
    );

    IF v_activity_id IS NOT NULL AND v_campaign_id IS NOT NULL THEN
      IF v_any_explicit THEN
        -- Pick the informative end: best positive if set, else worst negative, else 3.
        v_rating := COALESCE(v_best_positive, v_worst_negative, 3);
      ELSE
        -- Legacy composite
        IF v_positive_count > 0 AND v_negative_count = 0 THEN
          v_rating := 4;  -- NOTE: legacy value; migrate existing outcomes to
                          -- explicit mapping to get the correct 1..5 spread.
        ELSIF v_positive_count > 0 AND v_negative_count > 0 THEN
          v_rating := 3;
        ELSIF v_negative_count > 0 THEN
          v_rating := 2;
        ELSE
          v_rating := 3;
        END IF;
      END IF;

      PERFORM record_assessment_event(
        p_activity_id := v_activity_id,
        p_worker_id := v_worker_id,
        p_rating := v_rating,
        p_binary_value := v_binary_value,
        p_rating_phase := 'actual',
        p_event_id := NULL,
        p_source := 'call_outcome',
        p_notes := p_overall_notes,
        p_actor_id := p_caller_user_id
      );
    END IF;
  END IF;

  -- 2e. Membership / ambition side effects
  PERFORM apply_call_outcome_side_effects(v_attempt_id, v_worker_id, v_campaign_id);

  -- 3. Determine new item status
  IF p_dial_disposition = 'callback_requested' OR p_call_disposition = 'partial_asked_callback' THEN
    v_item_status := 'deferred';
  ELSIF p_dial_disposition = 'connected' AND p_call_disposition IS NOT NULL THEN
    v_item_status := 'completed';
  ELSIF p_dial_disposition IN ('disconnected', 'wrong_number', 'do_not_call') THEN
    v_item_status := 'completed';
  ELSE
    v_item_status := 'pending';
  END IF;

  -- 4. Update call_list_items
  UPDATE call_list_items SET
    status = v_item_status,
    attempts_count = attempts_count + 1,
    last_attempt_at = now(),
    best_disposition = COALESCE(p_call_disposition, p_dial_disposition),
    next_call_at = p_callback_datetime,
    updated_at = now()
  WHERE item_id = p_list_item_id;

  -- 5. Update call_lists completed_items
  UPDATE call_lists SET
    completed_items = (
      SELECT COUNT(*) FROM call_list_items
      WHERE list_id = v_list_id AND status IN ('completed', 'skipped')
    ),
    updated_at = now()
  WHERE list_id = v_list_id;

  -- 6. Upsert worker_campaign_connections
  IF v_campaign_id IS NOT NULL THEN
    SELECT connection_id INTO v_connection_id
    FROM worker_campaign_connections
    WHERE worker_id = v_worker_id AND campaign_id = v_campaign_id;

    IF v_connection_id IS NULL THEN
      INSERT INTO worker_campaign_connections (
        worker_id, campaign_id, connection_status,
        first_contacted_at, last_contacted_at, contact_count,
        preferred_contact_method, support_level, created_by
      ) VALUES (
        v_worker_id, v_campaign_id,
        CASE
          WHEN p_dial_disposition = 'connected' THEN 'contacted'
          ELSE 'potential'
        END,
        now(), now(), 1,
        'phone',
        p_support_level,
        p_caller_user_id
      )
      RETURNING connection_id INTO v_connection_id;
    ELSE
      UPDATE worker_campaign_connections SET
        connection_status = CASE
          WHEN p_dial_disposition = 'connected'
            AND connection_status IN ('potential', 'contacted') THEN 'engaged'
          WHEN p_dial_disposition = 'connected' THEN connection_status
          ELSE connection_status
        END,
        last_contacted_at = now(),
        contact_count = contact_count + 1,
        support_level = COALESCE(p_support_level, support_level),
        updated_at = now()
      WHERE connection_id = v_connection_id;
    END IF;

    -- 7. Insert worker_activity_log
    INSERT INTO worker_activity_log (
      connection_id, activity_type, activity_date,
      description, outcome, contact_method,
      duration_minutes, logged_by
    ) VALUES (
      v_connection_id, 'contact', now(),
      COALESCE(p_overall_notes, 'Phone call attempt'),
      COALESCE(p_call_disposition, p_dial_disposition),
      'phone',
      CASE WHEN p_duration_seconds IS NOT NULL
        THEN CEIL(p_duration_seconds / 60.0)::INTEGER
        ELSE NULL
      END,
      p_caller_user_id
    );
  END IF;

  v_result := jsonb_build_object(
    'attempt_id', v_attempt_id,
    'item_status', v_item_status,
    'connection_id', v_connection_id,
    'worker_id', v_worker_id,
    'campaign_id', v_campaign_id
  );

  RETURN v_result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
